def main():
    audit=read(D/'dual_view_approach_40/independent_dual_view_audit_40.json');assert audit['software_audit_passed'];a=audit['staged_audit']
    diag=read(D/'support_diagnosis_41/recorded_support.json');screen=read(D/'terminal_screen_42/results.json');OUT.mkdir(exist_ok=False)
    dirs={'Original parent59117':D/'clearance_damped_01/baseline','Best normal3s':D/'normal_landing3s_06/candidate','Rear-only staged36':D/'staged_approach_36/candidate','Current fallback40':D/'dual_view_approach_40/candidate'}
    episodes={k:read(v/'results.json')['episodes'] for k,v in dirs.items()};candidate=episodes['Current fallback40']
    counts={k:dict(stable=sum(r['success'] for r in v),clean=sum(clean(r) for r in v),slip=sum(r['slip_ticks']>0 for r in v),contact=sum(r['failures']['forbidden'] or r['illegal_ticks']>0 for r in v),physical=sum(any(r['failures'].values()) for r in v),warnings=sum(r['traction_bad_ticks']>0 for r in v)) for k,v in episodes.items()}
    pairs={};per_case=[];windows=['metrics_whole_trial','metrics_last10s','metrics_last5s'];keys=['total_squared_torque_Nm2','total_absolute_torque_Nm','all_joint_rms_Nm','leg_squared_torque_Nm2','upper_squared_torque_Nm2']
