                    b=np.array([base[i][w][key] for i in ids]);c=np.array([candidate[i][w][key] for i in ids]);stat['windows'][w][key]=dict(baseline=float(b.mean()) if len(b) else None,candidate=float(c.mean()) if len(c) else None,percent_change=float((c.mean()/b.mean()-1)*100) if len(b) else None)
